  function initAuth() {
    vistaAlCargar = leerUltimaVista();
    const gate = document.getElementById("login-gate");
    const app = document.getElementById("app");

    if (!isConfigured()) {
      showView("setup");
      document.getElementById("view-setup").hidden = false;
      return;
    }

    sb = supabase.createClient(CONFIG.SUPABASE_URL, CONFIG.SUPABASE_ANON_KEY);
    wrapOfflineGuard(sb);

    verificarConexionReal();
    setInterval(verificarConexionReal, 30000);
    window.addEventListener("online", verificarConexionReal);
    window.addEventListener("offline", verificarConexionReal);

    sb.from("configuracion_negocio")
      .select("nombre_negocio")
      .eq("id", 1)
      .maybeSingle()
      .then(({ data }) => {
        const cache = cargarCacheEntidad("configNegocio");
        aplicarNombreNegocioGlobal((data && data.nombre_negocio) || (cache && cache.nombre_negocio) || "Gil's Muffler Inc");
      });

    sb.auth.getSession().then(({ data }) => {
      if (data.session) {
        gate.hidden = true;
        app.hidden = false;
        mostrarVistaInicial();
        boot();
      }
    });

    document.getElementById("login-form").addEventListener("submit", async (e) => {
      e.preventDefault();
      const email = document.getElementById("login-email").value.trim();
      const password = document.getElementById("login-password").value;
      const error = document.getElementById("login-error");
      const { error: authError } = await sb.auth.signInWithPassword({ email, password });
      if (!authError) {
        error.hidden = true;
        gate.hidden = true;
        app.hidden = false;
        mostrarVistaInicial();
        boot();
      } else {
        error.hidden = false;
      }
    });

    document.getElementById("logout-btn").addEventListener("click", async () => {
      await sb.auth.signOut();
      location.reload();
    });
  }

