  const VIEW_SEARCH_INPUT = { clientes: "clientes-search", facturas: "facturas-search", estimados: "estimados-search", inventario: "piezas-search", ordenes: "ordenes-search" };
  const VIEW_NEW_BUTTON = {
    clientes: "btn-nuevo-cliente",
    facturas: "btn-nueva-factura",
    estimados: "btn-nuevo-estimado",
    reservas: "btn-nueva-reserva",
    ordenes: "btn-nueva-orden",
    inventario: "btn-nueva-pieza",
    llamadas: "btn-nueva-llamada",
  };

  function initKeyboardShortcuts() {
    document.addEventListener("keydown", (e) => {
      const typing = e.target.matches("input, textarea, select");

      if (e.key === "Escape") {
        if (closeTopModal()) e.preventDefault();
        return;
      }

      if (typing || anyModalOpen()) return;

      if (e.key === "/") {
        const inputId = VIEW_SEARCH_INPUT[currentViewName()];
        if (inputId) {
          e.preventDefault();
          document.getElementById(inputId).focus();
        }
        return;
      }

      if (e.key.toLowerCase() === "n" && !e.ctrlKey && !e.metaKey && !e.altKey) {
        const btnId = VIEW_NEW_BUTTON[currentViewName()];
        if (btnId) {
          e.preventDefault();
          document.getElementById(btnId).click();
        }
        return;
      }

      if (e.key === "?") {
        e.preventDefault();
        openModal("modal-shortcuts");
      }
    });
  }

  function showView(name) {
    [
      "setup",
      "dashboard",
      "clientes",
      "cliente-detalle",
      "cliente-nuevo",
      "reservas",
      "ordenes",
      "inventario",
      "llamadas",
      "turnos",
      "facturas",
      "invoices-due",
      "invoices-paid",
      "estimados",
      "registro-diario",
      "configuracion",
    ].forEach((v) => {
      const el = document.getElementById("view-" + v);
      if (v === name) {
        el.hidden = false;
        el.classList.remove("is-visible");
        requestAnimationFrame(() => el.classList.add("is-visible"));
      } else {
        el.classList.remove("is-visible");
        el.hidden = true;
      }
    });
    guardarUltimaVista(name);
  }

