  async function abrirEscanerVin() {
    const estado = document.getElementById("escaner-vin-estado");
    estado.textContent = t("iniciando_camara");
    openModal("modal-escaner-vin");

    try {
      await cargarZXing();
    } catch (e) {
      estado.textContent = t("error_cargar_escaner_conexion");
      return;
    }

    const video = document.getElementById("video-escaner-vin");
    zxingReaderInstancia = new ZXing.BrowserMultiFormatReader();
    try {
      await zxingReaderInstancia.decodeFromConstraints({ video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } } }, video, (result) => {
        if (result) {
          const texto = result.getText().toUpperCase().replace(/[^A-Z0-9]/g, "");
          document.getElementById("vehiculo-vin").value = texto;
          closeModal("modal-escaner-vin");
          showToast("VIN detectado: " + texto);
          decodificarVinNHTSA(texto);
        }
      });
      estado.textContent = t("buscando_vin");
    } catch (e) {
      estado.textContent = t("error_acceso_camara");
    }
  }

  async function decodificarVinNHTSA(vin) {
    if (!vin || vin.length !== 17) return;
    try {
      const resp = await fetch("https://vpic.nhtsa.gov/api/vehicles/decodevin/" + encodeURIComponent(vin) + "?format=json");
      const data = await resp.json();
      const campos = {};
      (data.Results || []).forEach((r) => {
        if (r.Value && r.Value !== "Not Applicable") campos[r.Variable] = r.Value;
      });
      const marca = campos["Make"];
      const modelo = campos["Model"];
      const anio = campos["Model Year"];
      if (marca && !document.getElementById("vehiculo-marca").value.trim()) document.getElementById("vehiculo-marca").value = marca;
      if (modelo && !document.getElementById("vehiculo-modelo").value.trim()) document.getElementById("vehiculo-modelo").value = modelo;
      if (anio && !document.getElementById("vehiculo-anio").value.trim()) document.getElementById("vehiculo-anio").value = anio;
      if (marca || modelo || anio) showToast(t("vin_completado_msg"));
    } catch (e) {
      // Si falla la consulta del VIN, no pasa nada más — el VIN ya quedó guardado.
    }
  }

  function toTitleCaseSimple(texto) {
    return (texto || "")
      .toLowerCase()
      .split(" ")
      .filter(Boolean)
      .map((p) => p[0].toUpperCase() + p.slice(1))
      .join(" ");
  }

  // Lista oficial de códigos de campo AAMVA (licencias de EE.UU.). Algunos
  // escáneres/licencias no separan los campos con salto de línea — vienen
  // todos pegados en una sola cadena (ej. "...DCSVASQUEZDACLUIS...") — así
  // que hay que buscar dónde empieza cada código conocido en vez de partir
  // por línea.
  const AAMVA_CODIGOS = [
    "DCA", "DCB", "DCD", "DBA", "DCS", "DAC", "DAD", "DBD", "DBB", "DBC",
    "DAY", "DAU", "DAG", "DAH", "DAI", "DAJ", "DAK", "DAQ", "DCF", "DCG",
    "DAA", "DAB", "DAE", "DAF", "DAH", "DAI", "DAW", "DAZ", "DCE", "DCH",
    "DCI", "DCJ", "DCK", "DCL", "DCM", "DCN", "DCO", "DCP", "DCQ", "DCR",
    "DCT", "DCU", "DDA", "DDB", "DDC", "DDD", "DDE", "DDF", "DDG", "DDH",
    "DDI", "DDJ", "DDK", "DDL",
  ];

  function parseAAMVA(texto) {
    const campos = {};
    const limpio = texto.replace(/[\n\r\x1e\x1f]+/g, "");
    const patron = new RegExp("(?=" + AAMVA_CODIGOS.join("|") + ")", "g");
    limpio.split(patron).forEach((trozo) => {
      const codigo = trozo.slice(0, 3);
      const valor = trozo.slice(3).trim();
      if (AAMVA_CODIGOS.includes(codigo) && valor) campos[codigo] = valor;
    });
    return {
      nombre: campos.DAC || campos.DCT || "",
      apellido: campos.DCS || "",
      direccion: campos.DAG || "",
      ciudad: campos.DAI || "",
      estado: campos.DAJ || "",
    };
  }

  function aplicarDatosLicenciaEscaneada(textoCrudo) {
    const datos = parseAAMVA(textoCrudo);
    if (!datos.nombre && !datos.apellido) return false;
    if (datos.nombre) document.getElementById("cliente-nombre").value = toTitleCaseSimple(datos.nombre);
    if (datos.apellido) document.getElementById("cliente-apellido").value = toTitleCaseSimple(datos.apellido);
    if (datos.direccion) {
      document.getElementById("cliente-direccion").value =
        toTitleCaseSimple(datos.direccion) +
        (datos.ciudad ? ", " + toTitleCaseSimple(datos.ciudad) : "") +
        (datos.estado ? ", " + datos.estado : "");
    }
    actualizarPreviewCliente();
    guardarBorradorCliente();
    showToast(t("licencia_detectada_msg"));
    return true;
  }

  function procesarEscaneoUsbLicencia() {
    const input = document.getElementById("cliente-escaner-usb-input");
    const texto = input.value;
    input.value = "";
    if (!texto.trim()) return;
    if (!aplicarDatosLicenciaEscaneada(texto)) {
      showToast(t("licencia_usb_sin_datos"), true);
    }
  }

  async function abrirEscanerLicencia() {
    const estado = document.getElementById("escaner-licencia-estado");
    estado.textContent = t("iniciando_camara");
    openModal("modal-escaner-licencia");

    try {
      await cargarZXing();
    } catch (e) {
      estado.textContent = t("error_cargar_escaner_conexion");
      return;
    }

    const video = document.getElementById("video-escaner-licencia");
    const hints = new Map();
    hints.set(ZXing.DecodeHintType.POSSIBLE_FORMATS, [ZXing.BarcodeFormat.PDF_417]);
    zxingLicenciaInstancia = new ZXing.BrowserMultiFormatReader(hints);
    try {
      await zxingLicenciaInstancia.decodeFromConstraints({ video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } } }, video, (result) => {
        if (!result) return;
        if (!aplicarDatosLicenciaEscaneada(result.getText())) return;
        closeModal("modal-escaner-licencia");
      });
      estado.textContent = t("buscando_licencia");
    } catch (e) {
      estado.textContent = t("error_acceso_camara");
    }
  }

  function cargarTesseract() {
    if (window.Tesseract) return Promise.resolve();
    return new Promise((resolve, reject) => {
      const script = document.createElement("script");
      script.src = "https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js";
      script.onload = () => resolve();
      script.onerror = () => reject(new Error(t("error_cargar_escaner")));
      document.head.appendChild(script);
    });
  }

  async function abrirEscanerPlaca() {
    const estado = document.getElementById("escaner-placa-estado");
    estado.textContent = t("iniciando_camara");
    openModal("modal-escaner-placa");

    const video = document.getElementById("video-escaner-placa");
    try {
      placaStreamInstancia = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } } });
      video.srcObject = placaStreamInstancia;
      await video.play();
      estado.textContent = "";
    } catch (e) {
      estado.textContent = t("error_acceso_camara");
    }
  }

  async function capturarPlaca() {
    const estado = document.getElementById("escaner-placa-estado");
    const video = document.getElementById("video-escaner-placa");
    const canvas = document.getElementById("canvas-escaner-placa");
    if (!video.videoWidth) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext("2d").drawImage(video, 0, 0, canvas.width, canvas.height);

    estado.textContent = t("leyendo_placa");
    try {
      await cargarTesseract();
      const worker = await Tesseract.createWorker("eng");
      const { data } = await worker.recognize(canvas);
      await worker.terminate();
      const texto = (data.text || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
      if (texto.length >= 4 && texto.length <= 8) {
        document.getElementById("cliente-vehiculo-placa").value = texto;
        guardarBorradorCliente();
        closeModal("modal-escaner-placa");
        showToast(t("placa_detectada_msg"));
      } else {
        estado.textContent = t("placa_no_detectada");
      }
    } catch (e) {
      estado.textContent = t("placa_no_detectada");
    }
  }

  async function openVehiculoModal(vehiculo, clienteId) {
    document.getElementById("modal-vehiculo-title").textContent = vehiculo ? t("editar_vehiculo_titulo") : t("nuevo_vehiculo_titulo");
    document.getElementById("vehiculo-id").value = vehiculo ? vehiculo.id : "";
    document.getElementById("vehiculo-cliente-id").value = vehiculo ? vehiculo.cliente_id : clienteId;
    document.getElementById("vehiculo-marca").value = vehiculo ? vehiculo.marca || "" : "";
    document.getElementById("vehiculo-modelo").value = vehiculo ? vehiculo.modelo || "" : "";
    document.getElementById("vehiculo-anio").value = vehiculo ? vehiculo.anio || "" : "";
    document.getElementById("vehiculo-placa").value = vehiculo ? vehiculo.placa || "" : "";
    document.getElementById("vehiculo-vin").value = vehiculo ? vehiculo.vin || "" : "";
    document.getElementById("vehiculo-kilometraje").value = vehiculo ? vehiculo.kilometraje || "" : "";
    document.getElementById("vehiculo-notas").value = vehiculo ? vehiculo.notas || "" : "";
    document.getElementById("vehiculo-recordatorio-activo").checked = vehiculo ? !!vehiculo.recordatorio_activo : false;
    document.getElementById("vehiculo-recordatorio-frecuencia").value = vehiculo ? vehiculo.recordatorio_frecuencia_meses || 3 : 3;
    document.getElementById("vehiculo-recordatorio-ultima").value = vehiculo && vehiculo.recordatorio_ultima_fecha ? vehiculo.recordatorio_ultima_fecha : "";
    document.getElementById("vehiculo-recordatorio-proxima").value = vehiculo && vehiculo.recordatorio_proxima_fecha ? vehiculo.recordatorio_proxima_fecha : "";
    document.getElementById("btn-eliminar-vehiculo").hidden = !vehiculo;
    const clienteDelVehiculo = state.clientes.find((c) => c.id === (vehiculo ? vehiculo.cliente_id : clienteId));
    document.getElementById("btn-guardar-y-agregar-otro-vehiculo").hidden = !(!vehiculo && esClienteDealer(clienteDelVehiculo));

    const historialWrap = document.getElementById("vehiculo-historial-wrap");
    const historialEl = document.getElementById("vehiculo-historial");
    if (vehiculo) {
      historialWrap.hidden = false;
      historialEl.innerHTML = '<p class="detalle-empty">Cargando…</p>';
      openModal("modal-vehiculo");

      const ordenesVehiculo = state.ordenes.filter((o) => o.vehiculo_id === vehiculo.id && o.kilometraje);
      const kmHistorial = await fetchKilometrajeHistorial(vehiculo.id);

      const lecturas = [
        ...ordenesVehiculo.map((o) => ({
          fecha: o.fecha_recepcion,
          kilometraje: o.kilometraje,
          fuente: "Orden #" + String(o.numero).padStart(4, "0"),
        })),
        ...kmHistorial.map((k) => ({ fecha: k.fecha, kilometraje: k.kilometraje, fuente: t("actualizacion_manual") })),
      ].sort((a, b) => (a.fecha < b.fecha ? 1 : -1));

      historialEl.innerHTML = lecturas.length
        ? lecturas
            .map(
              (l) =>
                '<div class="detalle-list-item"><span class="historial-fecha">' +
                escapeHtml(formatDate(l.fecha)) +
                '</span><span style="flex:1;">' +
                escapeHtml(l.fuente) +
                "</span><span>" +
                escapeHtml(l.kilometraje + " mi") +
                "</span></div>"
            )
            .join("")
        : '<p class="detalle-empty">Sin lecturas de kilometraje registradas todavía.</p>';
    } else {
      historialWrap.hidden = true;
      historialEl.innerHTML = "";
      openModal("modal-vehiculo");
    }
  }

  async function fetchKilometrajeHistorial(vehiculoId) {
    const { data, error } = await sb
      .from("kilometraje_historial")
      .select("*")
      .eq("vehiculo_id", vehiculoId)
      .order("fecha", { ascending: false });
    if (error) return [];
    return data;
  }

  async function registrarKilometraje(vehiculoId, kilometraje) {
    if (!vehiculoId || !kilometraje) return;
    await sb.from("kilometraje_historial").insert({ vehiculo_id: vehiculoId, kilometraje, fecha: todayISO() });
  }

  async function guardarVehiculoDesdeFormulario() {
    const id = document.getElementById("vehiculo-id").value;
    const vehiculoAnterior = id ? state.vehiculos.find((v) => v.id === id) : null;
    const payload = {
      cliente_id: document.getElementById("vehiculo-cliente-id").value,
      marca: document.getElementById("vehiculo-marca").value.trim(),
      modelo: document.getElementById("vehiculo-modelo").value.trim(),
      anio: document.getElementById("vehiculo-anio").value.trim(),
      placa: document.getElementById("vehiculo-placa").value.trim(),
      vin: document.getElementById("vehiculo-vin").value.trim(),
      kilometraje: document.getElementById("vehiculo-kilometraje").value.trim(),
      notas: document.getElementById("vehiculo-notas").value.trim(),
      recordatorio_activo: document.getElementById("vehiculo-recordatorio-activo").checked,
      recordatorio_frecuencia_meses: parseInt(document.getElementById("vehiculo-recordatorio-frecuencia").value, 10) || 3,
      recordatorio_ultima_fecha: document.getElementById("vehiculo-recordatorio-ultima").value || null,
      recordatorio_proxima_fecha: document.getElementById("vehiculo-recordatorio-proxima").value || null,
    };

    let error;
    let vehiculoId = id;
    if (id) {
      ({ error } = await sb.from("vehiculos").update(payload).eq("id", id));
    } else {
      const inserted = await sb.from("vehiculos").insert(payload).select().single();
      error = inserted.error;
      vehiculoId = inserted.data ? inserted.data.id : null;
    }

    if (error) {
      console.error(error);
      showToast(t("error_guardar_vehiculo"), true);
      return null;
    }

    if (payload.kilometraje && (!vehiculoAnterior || vehiculoAnterior.kilometraje !== payload.kilometraje)) {
      await registrarKilometraje(vehiculoId, payload.kilometraje);
    }

    return payload;
  }

  async function saveVehiculo(e) {
    e.preventDefault();
    const payload = await guardarVehiculoDesdeFormulario();
    if (!payload) return;

    closeModal("modal-vehiculo");
    showToast(t("vehiculo_guardado"));
    await refreshVehiculos();
    const cliente = state.clientes.find((c) => c.id === payload.cliente_id);
    if (cliente) openClienteDetalle(cliente);
  }

  async function guardarYAgregarOtroVehiculo() {
    const payload = await guardarVehiculoDesdeFormulario();
    if (!payload) return;

    showToast(t("vehiculo_guardado"));
    await refreshVehiculos();
    openVehiculoModal(null, payload.cliente_id);
  }

  async function deleteVehiculo() {
    const id = document.getElementById("vehiculo-id").value;
    if (!id) return;
    if (!(await confirmDialog(t("confirm_eliminar_vehiculo"), { title: t("eliminar_vehiculo_titulo") }))) return;

    const clienteId = document.getElementById("vehiculo-cliente-id").value;
    const { error } = await sb.from("vehiculos").delete().eq("id", id);
    if (error) {
      if (error.code === "23503") {
        showToast(t("error_eliminar_ordenes_asociadas"), true);
      } else {
        showToast(t("error_eliminar_vehiculo"), true);
      }
      return;
    }

    closeModal("modal-vehiculo");
    showToast(t("vehiculo_eliminado"));
    await refreshVehiculos();
    const cliente = state.clientes.find((c) => c.id === clienteId);
    if (cliente) openClienteDetalle(cliente);
  }

