  async function mostrarHistorialPrecios() {
    const { data, error } = await sb
      .from("pieza_precio_historial")
      .select("*, piezas(nombre)")
      .order("fecha", { ascending: false })
      .order("created_at", { ascending: false });

    const tbody = document.getElementById("historial-precios-tbody");
    if (error || !data || !data.length) {
      tbody.innerHTML = "<tr><td colspan='6'>" + t("sin_cambios_precio") + "</td></tr>";
      openModal("modal-historial-precios");
      return;
    }

    const porPieza = new Map();
    data.forEach((row) => {
      if (!porPieza.has(row.pieza_id)) porPieza.set(row.pieza_id, []);
      porPieza.get(row.pieza_id).push(row);
    });

    tbody.innerHTML = data
      .map((row) => {
        const historialPieza = porPieza.get(row.pieza_id);
        const anterior = historialPieza[historialPieza.indexOf(row) + 1];
        let cambioHtml = "—";
        if (anterior) {
          const diff = Number(row.precio_venta) - Number(anterior.precio_venta);
          if (diff > 0) cambioHtml = "<span class='pill pill-stock-bajo'>▲ " + money(diff) + "</span>";
          else if (diff < 0) cambioHtml = "<span class='pill pill-stock-ok'>▼ " + money(Math.abs(diff)) + "</span>";
          else cambioHtml = "Sin cambio";
        }
        return (
          "<tr><td>" +
          escapeHtml(row.piezas ? row.piezas.nombre : "—") +
          "</td><td>" +
          escapeHtml(row.proveedor || "—") +
          "</td><td>" +
          escapeHtml(formatDate(row.fecha)) +
          "</td><td>" +
          money(row.costo) +
          "</td><td>" +
          money(row.precio_venta) +
          "</td><td>" +
          cambioHtml +
          "</td></tr>"
        );
      })
      .join("");

    openModal("modal-historial-precios");
  }

  function calcularSugerenciaPedido(pieza) {
    const limite = new Date();
    limite.setDate(limite.getDate() - 90);
    const limiteISO = limite.toISOString();
    const consumoReciente = state.piezaStockHistorial
      .filter((m) => m.pieza_id === pieza.id && Number(m.cambio) < 0 && m.creado_en >= limiteISO)
      .reduce((sum, m) => sum + Math.abs(Number(m.cambio)), 0);

    if (consumoReciente > 0) {
      const consumoMensual = consumoReciente / 3;
      const sugerido = Math.max(Math.ceil(consumoMensual * 2 - Number(pieza.stock)), Number(pieza.stock_minimo) || 1);
      return { cantidad: sugerido, basadoEnUso: true };
    }
    const sugeridoSimple = Math.max(Number(pieza.stock_minimo) * 2 - Number(pieza.stock), Number(pieza.stock_minimo) || 1);
    return { cantidad: Math.ceil(sugeridoSimple), basadoEnUso: false };
  }

  function mostrarParaReordenar() {
    const bajas = state.piezas.filter((p) => Number(p.stock) <= Number(p.stock_minimo));
    const tbody = document.getElementById("reordenar-tbody");
    tbody.innerHTML = bajas.length
      ? bajas
          .map((p) => {
            const sugerencia = calcularSugerenciaPedido(p);
            return (
              "<tr><td>" +
              escapeHtml(p.nombre) +
              "</td><td>" +
              escapeHtml(p.proveedor || "—") +
              "</td><td>" +
              p.stock +
              "</td><td>" +
              p.stock_minimo +
              "</td><td>" +
              sugerencia.cantidad +
              (sugerencia.basadoEnUso ? ' <span class="view-sub" style="margin:0;">(' + t("sugerencia_pedido_uso_real") + ")</span>" : "") +
              "</td></tr>"
            );
          })
          .join("")
      : "<tr><td colspan='5'>" + t("sin_piezas_reordenar") + "</td></tr>";
    openModal("modal-reordenar");
  }

