  function motivoPiezaLabel(motivo) {
    if (motivo === "escaneo") return t("motivo_escaneo");
    if (motivo === "recepcion_pedido") return t("motivo_recepcion_pedido");
    return t("motivo_ajuste_manual");
  }

  let recibirPedidoLista = [];

  function agregarARecibirPedido(codigo) {
    const sku = (codigo || "").trim();
    if (!sku) return;
    const pieza = state.piezas.find((p) => (p.sku || "").toLowerCase() === sku.toLowerCase());
    if (!pieza) {
      showToast(t("recibir_pedido_pieza_no_encontrada", { sku }), true);
      return;
    }
    const existente = recibirPedidoLista.find((it) => it.pieza.id === pieza.id);
    if (existente) existente.cantidad += 1;
    else recibirPedidoLista.push({ pieza, cantidad: 1 });
    renderRecibirPedidoLista();
  }

  function renderRecibirPedidoLista() {
    const el = document.getElementById("recibir-pedido-lista");
    const vacio = document.getElementById("recibir-pedido-vacio");
    vacio.hidden = recibirPedidoLista.length !== 0;
    el.innerHTML = recibirPedidoLista
      .map(
        (it, idx) =>
          '<div class="detalle-list-item"><span style="flex:1;">' +
          escapeHtml(it.pieza.nombre) +
          " (" +
          escapeHtml(it.pieza.sku || "—") +
          ')</span><button type="button" class="recibir-pedido-cantidad-btn" data-recibir-menos="' +
          idx +
          '" aria-label="' + escapeHtml(t("pieza_restar_stock_label", { nombre: it.pieza.nombre })) + '">−</button><span class="recibir-pedido-cantidad">' +
          it.cantidad +
          '</span><button type="button" class="recibir-pedido-cantidad-btn" data-recibir-mas="' +
          idx +
          '" aria-label="' + escapeHtml(t("pieza_sumar_stock_label", { nombre: it.pieza.nombre })) + '">+</button><button type="button" class="icon-btn" data-recibir-quitar="' +
          idx +
          '" aria-label="' + t("quitar_fila_title") + '">&times;</button></div>'
      )
      .join("");

    el.querySelectorAll("[data-recibir-menos]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const idx = Number(btn.dataset.recibirMenos);
        recibirPedidoLista[idx].cantidad = Math.max(1, recibirPedidoLista[idx].cantidad - 1);
        renderRecibirPedidoLista();
      });
    });
    el.querySelectorAll("[data-recibir-mas]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const idx = Number(btn.dataset.recibirMas);
        recibirPedidoLista[idx].cantidad += 1;
        renderRecibirPedidoLista();
      });
    });
    el.querySelectorAll("[data-recibir-quitar]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const idx = Number(btn.dataset.recibirQuitar);
        recibirPedidoLista.splice(idx, 1);
        renderRecibirPedidoLista();
      });
    });
  }

  function abrirRecibirPedido() {
    recibirPedidoLista = [];
    renderRecibirPedidoLista();
    document.getElementById("recibir-pedido-input").value = "";
    openModal("modal-recibir-pedido");
  }

  async function confirmarRecibirPedido() {
    if (!recibirPedidoLista.length) return;
    for (const it of recibirPedidoLista) {
      const pieza = state.piezas.find((p) => p.id === it.pieza.id);
      if (!pieza) continue;
      const nuevoStock = (Number(pieza.stock) || 0) + it.cantidad;
      await sb.from("piezas").update({ stock: nuevoStock }).eq("id", pieza.id);
      await sb.from("pieza_stock_historial").insert({ pieza_id: pieza.id, cambio: it.cantidad, stock_resultante: nuevoStock, motivo: "recepcion_pedido" });
    }
    const cantidadTotal = recibirPedidoLista.length;
    closeModal("modal-recibir-pedido");
    showToast(t("recibir_pedido_confirmado_msg", { cantidad: cantidadTotal }));
    recibirPedidoLista = [];
    await refreshPiezas();
    await refreshPiezaStockHistorial();
  }

  function cargarJsBarcode() {
    if (window.JsBarcode) return Promise.resolve();
    return new Promise((resolve, reject) => {
      const script = document.createElement("script");
      script.src = "https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js";
      script.onload = () => resolve();
      script.onerror = () => reject(new Error(t("error_cargar_escaner")));
      document.head.appendChild(script);
    });
  }

  async function imprimirEtiquetaPieza() {
    const id = document.getElementById("pieza-id").value;
    const pieza = state.piezas.find((p) => p.id === id);
    if (!pieza) return;
    if (!pieza.sku) {
      showToast(t("etiqueta_sin_sku_msg"), true);
      return;
    }
    try {
      await cargarJsBarcode();
    } catch (e) {
      showToast(t("error_cargar_escaner_conexion"), true);
      return;
    }
    const svgTemp = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    JsBarcode(svgTemp, pieza.sku, { format: "CODE128", displayValue: true, height: 60, width: 2 });
    const barcodeSvg = svgTemp.outerHTML;

    const ventana = window.open("", "_blank", "width=420,height=320");
    if (!ventana) {
      showToast(t("error_ventana_bloqueada"), true);
      return;
    }
    ventana.document.write(
      "<html><head><title>" +
        escapeHtml(pieza.nombre) +
        "</title></head><body style='font-family:Arial,sans-serif;text-align:center;padding:1.2rem;'>" +
        "<div style='font-weight:700;font-size:1.05rem;'>" +
        escapeHtml(pieza.nombre) +
        "</div><div style='font-size:.9rem;color:#555;margin:.2rem 0 .6rem;'>" +
        escapeHtml(money(pieza.precio_venta)) +
        "</div>" +
        barcodeSvg +
        "<script>window.onload=function(){window.print();}<" +
        "/script></body></html>"
    );
    ventana.document.close();
  }

  async function savePieza(e) {
    e.preventDefault();
    const id = document.getElementById("pieza-id").value;
    const payload = {
      nombre: document.getElementById("pieza-nombre").value.trim(),
      sku: document.getElementById("pieza-sku").value.trim(),
      categoria: document.getElementById("pieza-categoria").value.trim(),
      costo: parseFloat(document.getElementById("pieza-costo").value) || 0,
      precio_venta: parseFloat(document.getElementById("pieza-precio").value) || 0,
      stock: parseFloat(document.getElementById("pieza-stock").value) || 0,
      stock_minimo: parseFloat(document.getElementById("pieza-stock-minimo").value) || 0,
      proveedor: document.getElementById("pieza-proveedor").value.trim(),
      ubicacion: document.getElementById("pieza-ubicacion").value.trim(),
      notas: document.getElementById("pieza-notas").value.trim(),
    };

    const anterior = id ? state.piezas.find((p) => p.id === id) : null;
    const precioCambio = !anterior || Number(anterior.costo) !== payload.costo || Number(anterior.precio_venta) !== payload.precio_venta;
    const deltaStock = payload.stock - (anterior ? Number(anterior.stock) || 0 : 0);

    let error;
    let piezaId = id;
    if (id) {
      ({ error } = await sb.from("piezas").update(payload).eq("id", id));
    } else {
      const { data, error: insError } = await sb.from("piezas").insert(payload).select().single();
      error = insError;
      if (data) piezaId = data.id;
    }

    if (error) {
      showToast("No se pudo guardar la pieza.", true);
      return;
    }

    if (precioCambio && piezaId) {
      await sb.from("pieza_precio_historial").insert({
        pieza_id: piezaId,
        costo: payload.costo,
        precio_venta: payload.precio_venta,
        proveedor: payload.proveedor,
      });
    }

    if (deltaStock !== 0 && piezaId) {
      await sb.from("pieza_stock_historial").insert({
        pieza_id: piezaId,
        cambio: deltaStock,
        stock_resultante: payload.stock,
        motivo: "manual",
      });
    }

    closeModal("modal-pieza");
    showToast("Pieza guardada.");
    await refreshPiezas();
    await refreshPiezaStockHistorial();
  }

  async function deletePieza() {
    const id = document.getElementById("pieza-id").value;
    if (!id) return;
    if (!(await confirmDialog(t("confirm_eliminar_pieza"), { title: t("eliminar_pieza_titulo") }))) return;

    const { error } = await sb.from("piezas").delete().eq("id", id);
    if (error) {
      if (error.code === "23503") {
        showToast(t("error_pieza_en_uso"), true);
      } else {
        showToast("No se pudo eliminar la pieza.", true);
      }
      return;
    }

    closeModal("modal-pieza");
    showToast("Pieza eliminada.");
    await refreshPiezas();
  }

  async function refreshPiezas() {
    renderSkeletonRows("piezas-tbody", 6, 4);
    state.piezas = await fetchPiezas();
    renderPiezas(filterPiezas());
    renderDashboard();
    populatePiezasDatalist();
  }

  function populatePiezasDatalist() {
    const datalist = document.getElementById("piezas-datalist");
    if (!datalist) return;
    datalist.innerHTML = state.piezas.map((p) => '<option value="' + escapeHtml(p.nombre) + '">' + escapeHtml(p.nombre) + " — " + money(p.precio_venta) + "</option>").join("");
  }

  // ---------------- render: órdenes de servicio (kanban) ----------------

  function filterOrdenes() {
    const q = document.getElementById("ordenes-search").value.trim().toLowerCase();
    if (!q) return state.ordenes;
    return state.ordenes.filter((o) => {
      const clienteNombre = (o.clientes ? o.clientes.nombre : "").toLowerCase();
      const vehiculo = [o.vehiculo_marca, o.vehiculo_modelo, o.vehiculo_placa].filter(Boolean).join(" ").toLowerCase();
      const numero = String(o.numero);
      return clienteNombre.includes(q) || vehiculo.includes(q) || numero.includes(q);
    });
  }

  function renderOrdenesKanban() {
    const kanban = document.getElementById("ordenes-kanban");
    kanban.innerHTML = "";
    const ordenesFiltradas = filterOrdenes();

    ETAPAS.forEach((etapa) => {
      const ordenesEtapa = ordenesFiltradas.filter((o) => o.etapa === etapa.key);
      const col = document.createElement("div");
      col.className = "kanban-column etapa-" + etapa.key;
      col.innerHTML =
        '<div class="kanban-column-header"><span class="kanban-column-title">' +
        t(etapa.labelKey) +
        '</span><span class="kanban-column-count">' +
        ordenesEtapa.length +
        "</span></div>" +
        '<div class="kanban-column-body"></div>';

      const body = col.querySelector(".kanban-column-body");
      if (!ordenesEtapa.length) {
        body.innerHTML = '<p class="kanban-empty">Sin órdenes aquí.</p>';
      }

      ordenesEtapa.forEach((o) => {
        const clienteNombre = o.clientes ? o.clientes.nombre : "—";
        const vehiculo = [o.vehiculo_marca, o.vehiculo_modelo].filter(Boolean).join(" ");
        const card = document.createElement("div");
        card.className = "kanban-card";
        card.dataset.ordenId = o.id;
        card.innerHTML =
          '<span class="kanban-card-title">#' +
          String(o.numero).padStart(4, "0") +
          " — " +
          avatarHtml(clienteNombre, "avatar-sm") +
          escapeHtml(clienteNombre) +
          "</span>" +
          '<span class="kanban-card-sub">' +
          escapeHtml(vehiculo || t("sin_vehiculo_opcion")) +
          "</span>" +
          (o.diagnostico ? '<span class="kanban-card-diag">' + escapeHtml(o.diagnostico) + "</span>" : "") +
          '<div class="kanban-card-actions"></div>';

        makeRowActivatable(card, (e) => {
          if (e.target.closest(".kanban-card-actions")) return;
          openOrdenModal(o);
        });

        const actions = card.querySelector(".kanban-card-actions");
        const next = nextEtapa(o.etapa);
        if (next) {
          const btn = document.createElement("button");
          btn.type = "button";
          btn.className = "kanban-card-next";
          btn.textContent = "Siguiente etapa →";
          btn.addEventListener("click", async (e) => {
            e.stopPropagation();
            await setOrdenEtapa(o.id, next);
          });
          actions.appendChild(btn);
        }

        const select = document.createElement("select");
        select.innerHTML = ETAPAS.map((et) => '<option value="' + et.key + '"' + (et.key === o.etapa ? " selected" : "") + ">" + t(et.labelKey) + "</option>").join("");
        select.addEventListener("click", (e) => e.stopPropagation());
        select.addEventListener("change", async (e) => {
          e.stopPropagation();
          await setOrdenEtapa(o.id, select.value);
        });
        actions.appendChild(select);

        body.appendChild(card);
      });

      kanban.appendChild(col);
    });
  }

  async function setOrdenEtapa(ordenId, etapa) {
    const { error } = await sb.from("ordenes_servicio").update({ etapa }).eq("id", ordenId);
    if (error) {
      showToast("No se pudo actualizar la etapa.", true);
      return;
    }
    showToast("Etapa actualizada.");
    await refreshOrdenes();

    if (etapa === "presupuesto") await crearLlamadaPendiente(ordenId, "presupuesto");
    if (etapa === "completado") await crearLlamadaPendiente(ordenId, "listo");
    await refreshLlamadas();

    const card = document.querySelector('.kanban-card[data-orden-id="' + ordenId + '"]');
    if (card) {
      card.classList.add("just-moved");
      card.scrollIntoView({ behavior: prefersReducedMotion() ? "auto" : "smooth", block: "nearest", inline: "center" });
      setTimeout(() => card.classList.remove("just-moved"), 900);
    }
  }

  function populateOrdenClienteSelect() {
    const select = document.getElementById("orden-cliente");
    const current = select.value;
    select.innerHTML = "";
    state.clientes.forEach((c) => {
      const opt = document.createElement("option");
      opt.value = c.id;
      opt.textContent = c.nombre;
      select.appendChild(opt);
    });
    if (current) select.value = current;
  }

  function populateOrdenVehiculoSelect(clienteId, selectedVehiculoId) {
    const select = document.getElementById("orden-vehiculo");
    select.innerHTML = "";
    state.vehiculos
      .filter((v) => v.cliente_id === clienteId)
      .forEach((v) => {
        const opt = document.createElement("option");
        opt.value = v.id;
        opt.textContent = vehiculoLabel(v) + (v.placa ? " — " + v.placa : "");
        select.appendChild(opt);
      });
    const optNuevo = document.createElement("option");
    optNuevo.value = "__nuevo__";
    optNuevo.textContent = t("btn_nuevo_vehiculo");
    select.appendChild(optNuevo);

    if (selectedVehiculoId && select.querySelector('option[value="' + selectedVehiculoId + '"]')) {
      select.value = selectedVehiculoId;
    }
    toggleOrdenVehiculoNuevo(select.value === "__nuevo__");
  }

  function toggleOrdenVehiculoNuevo(mostrar) {
    document.getElementById("orden-vehiculo-nuevo").hidden = !mostrar;
    if (mostrar) {
      document.getElementById("orden-nuevo-vehiculo-marca").value = "";
      document.getElementById("orden-nuevo-vehiculo-modelo").value = "";
      document.getElementById("orden-nuevo-vehiculo-anio").value = "";
      document.getElementById("orden-nuevo-vehiculo-placa").value = "";
    }
  }

  function addOrdenPiezaRow(item) {
    const tbody = document.getElementById("orden-piezas-tbody");
    const tr = document.createElement("tr");
    const options = state.piezas
      .map((p) => '<option value="' + p.id + '"' + (item && item.pieza_id === p.id ? " selected" : "") + ">" + escapeHtml(p.nombre) + "</option>")
      .join("");
    tr.innerHTML =
      '<td><select class="op-pieza"><option value="">— elegir —</option>' + options + "</select></td>" +
      '<td><input type="number" class="op-cant" min="0" step="0.01" value="' + (item ? item.cantidad : 1) + '" /></td>' +
      '<td><input type="number" class="op-precio" min="0" step="0.01" value="' + (item ? item.precio_unitario : 0) + '" /></td>' +
      '<td class="item-subtotal">$0.00</td>' +
      '<td><button type="button" class="item-remove" title="Quitar pieza">&times;</button></td>';
    tbody.appendChild(tr);

    const selectEl = tr.querySelector(".op-pieza");
    selectEl.addEventListener("change", () => {
      const pieza = state.piezas.find((p) => p.id === selectEl.value);
      if (pieza) tr.querySelector(".op-precio").value = pieza.precio_venta;
      recalcOrdenPiezasTotals();
    });
    tr.querySelectorAll(".op-cant, .op-precio").forEach((input) => {
      input.addEventListener("input", recalcOrdenPiezasTotals);
    });
    tr.querySelector(".item-remove").addEventListener("click", () => {
      tr.remove();
      recalcOrdenPiezasTotals();
    });

    recalcOrdenPiezasTotals();
  }

  function recalcOrdenPiezasTotals() {
    document.querySelectorAll("#orden-piezas-tbody tr").forEach((tr) => {
      const cant = parseFloat(tr.querySelector(".op-cant").value) || 0;
      const precio = parseFloat(tr.querySelector(".op-precio").value) || 0;
      tr.querySelector(".item-subtotal").textContent = money(cant * precio);
    });
  }

  function collectOrdenPiezas() {
    const rows = document.querySelectorAll("#orden-piezas-tbody tr");
    const items = [];
    rows.forEach((tr) => {
      const piezaId = tr.querySelector(".op-pieza").value;
      const cantidad = parseFloat(tr.querySelector(".op-cant").value) || 0;
      const precio = parseFloat(tr.querySelector(".op-precio").value) || 0;
      if (!piezaId || cantidad <= 0) return;
      items.push({ pieza_id: piezaId, cantidad, precio_unitario: precio });
    });
    return items;
  }

  async function openOrdenModal(orden) {
    document.getElementById("modal-orden-title").textContent = orden ? "Editar orden de servicio" : "Nueva orden de servicio";
    document.getElementById("orden-id").value = orden ? orden.id : "";
    const notaCreadorOrden = document.getElementById("orden-creado-por-nota");
    const nombreCreadorOrden = orden && orden.creado_por ? nombreEmpleado(orden.creado_por) : null;
    notaCreadorOrden.hidden = !nombreCreadorOrden;
    if (nombreCreadorOrden) notaCreadorOrden.textContent = "Creada por: " + nombreCreadorOrden;
    const btnCopiarOrden = document.getElementById("btn-copiar-link-orden");
    btnCopiarOrden.hidden = !orden;
    btnCopiarOrden.onclick = () => {
      const origen = typeof LAN_ORIGIN !== "undefined" && LAN_ORIGIN ? LAN_ORIGIN : location.origin;
      const url = origen + location.pathname.replace(/index\.html$/, "") + "ver-orden.html?id=" + orden.id;
      navigator.clipboard.writeText(url).then(
        () => showToast("Link copiado."),
        () => showToast("No se pudo copiar el link.", true)
      );
    };
    populateOrdenClienteSelect();
    document.getElementById("orden-cliente").value = orden ? orden.cliente_id : "";
    document.getElementById("orden-kilometraje").value = orden ? orden.kilometraje || "" : "";

    const clienteIdActual = orden ? orden.cliente_id : "";
    populateOrdenVehiculoSelect(clienteIdActual, orden ? orden.vehiculo_id : null);

    const legacyNota = document.getElementById("orden-vehiculo-legacy");
    if (orden && !orden.vehiculo_id && (orden.vehiculo_marca || orden.vehiculo_placa)) {
      legacyNota.hidden = false;
      legacyNota.textContent =
        t("vehiculo_legacy_prefijo") +
        [orden.vehiculo_marca, orden.vehiculo_modelo, orden.vehiculo_anio].filter(Boolean).join(" ") +
        (orden.vehiculo_placa ? " — " + orden.vehiculo_placa : "") +
        t("vehiculo_legacy_sufijo");
      if (document.getElementById("orden-vehiculo").value === "__nuevo__") {
        document.getElementById("orden-nuevo-vehiculo-marca").value = orden.vehiculo_marca || "";
        document.getElementById("orden-nuevo-vehiculo-modelo").value = orden.vehiculo_modelo || "";
        document.getElementById("orden-nuevo-vehiculo-anio").value = orden.vehiculo_anio || "";
        document.getElementById("orden-nuevo-vehiculo-placa").value = orden.vehiculo_placa || "";
      }
    } else {
      legacyNota.hidden = true;
      legacyNota.textContent = "";
    }

    document.getElementById("orden-fecha-recepcion").value = orden ? orden.fecha_recepcion : todayISO();
    document.getElementById("orden-fecha-estimada").value = orden ? orden.fecha_estimada || "" : "";
    document.getElementById("orden-diagnostico").value = orden ? orden.diagnostico || "" : "";
    document.getElementById("orden-trabajo").value = orden ? orden.trabajo_recomendado || "" : "";
    document.getElementById("orden-check-frenos").checked = orden ? !!orden.check_frenos : false;
    document.getElementById("orden-check-luces").checked = orden ? !!orden.check_luces : false;
    document.getElementById("orden-check-llantas").checked = orden ? !!orden.check_llantas : false;
    document.getElementById("orden-check-fluidos").checked = orden ? !!orden.check_fluidos : false;
    document.getElementById("orden-notas").value = orden ? orden.notas || "" : "";
    document.getElementById("btn-eliminar-orden").hidden = !orden;
    document.getElementById("btn-imprimir-orden").hidden = !orden;
    document.getElementById("btn-imprimir-orden").dataset.ordenId = orden ? orden.id : "";

    const nota = document.getElementById("orden-etapa-nota");
    if (orden) {
      nota.hidden = false;
      nota.textContent = t("etapa_actual_prefijo") + etapaLabel(orden.etapa) + t("etapa_actual_sufijo");
    } else {
      nota.hidden = true;
    }

    const generarBtn = document.getElementById("btn-generar-factura");
    generarBtn.hidden = !(orden && orden.etapa === "completado");

    document.getElementById("orden-piezas-tbody").innerHTML = "";
    if (orden) {
      ordenPiezasOriginal = await fetchOrdenPiezas(orden.id);
      if (ordenPiezasOriginal.length) {
        ordenPiezasOriginal.forEach(addOrdenPiezaRow);
      } else {
        addOrdenPiezaRow(null);
      }
    } else {
      ordenPiezasOriginal = [];
      addOrdenPiezaRow(null);
    }

    document.getElementById("orden-fotos-nota").hidden = !!orden;
    document.getElementById("btn-subir-orden-foto-label").hidden = !orden;
    if (orden) {
      await refreshOrdenFotos(orden.id);
    } else {
      document.getElementById("orden-fotos-grid").innerHTML = "";
    }

    renderFirmaEntrega(orden);

    openModal("modal-orden");
  }

  function renderFirmaEntrega(orden) {
    const seccion = document.getElementById("orden-firma-seccion");
    const puedeFirmar = !!(orden && (orden.etapa === "completado" || orden.etapa === "facturado"));
    seccion.hidden = !puedeFirmar;
    if (!puedeFirmar) return;

    const guardada = document.getElementById("orden-firma-guardada");
    const captura = document.getElementById("orden-firma-captura");
    if (orden.firma_entrega_url) {
      guardada.hidden = false;
      captura.hidden = true;
      guardada.innerHTML =
        '<img src="' +
        escapeHtml(orden.firma_entrega_url) +
        '" alt="Firma de entrega" style="max-width:400px;border:1px solid var(--border);border-radius:6px;background:#fff;" />' +
        "<p class='orden-nota'>Firmado por: " +
        escapeHtml(orden.firma_entrega_nombre || "—") +
        (orden.firma_entrega_fecha ? " — " + escapeHtml(formatDate(orden.firma_entrega_fecha.slice(0, 10))) : "") +
        "</p>" +
        '<button type="button" class="btn-ghost" id="btn-firmar-de-nuevo">Firmar de nuevo</button>';
      document.getElementById("btn-firmar-de-nuevo").addEventListener("click", () => {
        guardada.hidden = true;
        captura.hidden = false;
        initFirmaCanvas(document.getElementById("orden-firma-canvas"));
      });
    } else {
      guardada.hidden = true;
      captura.hidden = false;
      document.getElementById("orden-firma-nombre").value = "";
      initFirmaCanvas(document.getElementById("orden-firma-canvas"));
    }
  }

  let firmaCanvasCtx = null;
  let firmaDibujando = false;
  let firmaTieneTrazo = false;

  function initFirmaCanvas(canvas) {
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.lineWidth = 2;
    ctx.lineCap = "round";
    ctx.strokeStyle = "#1f2430";
    firmaCanvasCtx = ctx;
    firmaTieneTrazo = false;
    if (canvas._firmaBound) return;
    canvas._firmaBound = true;

    const posDesdeEvento = (e) => {
      const rect = canvas.getBoundingClientRect();
      return {
        x: ((e.clientX - rect.left) / rect.width) * canvas.width,
        y: ((e.clientY - rect.top) / rect.height) * canvas.height,
      };
    };

    canvas.addEventListener("pointerdown", (e) => {
      firmaDibujando = true;
      firmaTieneTrazo = true;
      const p = posDesdeEvento(e);
      firmaCanvasCtx.beginPath();
      firmaCanvasCtx.moveTo(p.x, p.y);
      e.preventDefault();
    });
    canvas.addEventListener("pointermove", (e) => {
      if (!firmaDibujando) return;
      const p = posDesdeEvento(e);
      firmaCanvasCtx.lineTo(p.x, p.y);
      firmaCanvasCtx.stroke();
      e.preventDefault();
    });
    ["pointerup", "pointerleave", "pointercancel"].forEach((evt) => {
      canvas.addEventListener(evt, () => {
        firmaDibujando = false;
      });
    });
  }

  function limpiarFirma() {
    const canvas = document.getElementById("orden-firma-canvas");
    firmaCanvasCtx.clearRect(0, 0, canvas.width, canvas.height);
    firmaTieneTrazo = false;
  }

  async function guardarFirmaEntrega() {
    const ordenId = document.getElementById("orden-id").value;
    const nombre = document.getElementById("orden-firma-nombre").value.trim();
    if (!ordenId) return;
    if (!nombre) {
      showToast(t("error_nombre_recibe_vacio"), true);
      return;
    }
    if (!firmaTieneTrazo) {
      showToast(t("error_firma_vacia"), true);
      return;
    }
    const canvas = document.getElementById("orden-firma-canvas");

    const blob = await new Promise((resolve) => canvas.toBlob(resolve, "image/png"));
    if (!blob) {
      showToast("No se pudo guardar la firma.", true);
      return;
    }
    const storagePath = "orden-" + ordenId + "/firma-" + crypto.randomUUID() + ".png";
    const { error: uploadError } = await sb.storage.from("fotos-ordenes").upload(storagePath, blob, { contentType: "image/png" });
    if (uploadError) {
      showToast("No se pudo subir la firma.", true);
      return;
    }
    const { data: urlData } = sb.storage.from("fotos-ordenes").getPublicUrl(storagePath);
    const { error: updateError } = await sb
      .from("ordenes_servicio")
      .update({
        firma_entrega_url: urlData.publicUrl,
        firma_entrega_nombre: nombre,
        firma_entrega_fecha: new Date().toISOString(),
      })
      .eq("id", ordenId);
    if (updateError) {
      showToast("No se pudo guardar la firma.", true);
      return;
    }
    showToast("Firma guardada.");
    await refreshOrdenes();
    renderFirmaEntrega(state.ordenes.find((o) => o.id === ordenId));
  }

  async function saveOrden(e) {
    e.preventDefault();
    const id = document.getElementById("orden-id").value;
    const clienteId = document.getElementById("orden-cliente").value;
    if (!clienteId) {
      showToast("Selecciona un cliente.", true);
      return;
    }

    const kilometrajeVisita = document.getElementById("orden-kilometraje").value.trim();
    let vehiculoId = document.getElementById("orden-vehiculo").value;
    let vehiculo = null;

    if (vehiculoId === "__nuevo__") {
      const nuevoVehiculo = {
        cliente_id: clienteId,
        marca: document.getElementById("orden-nuevo-vehiculo-marca").value.trim(),
        modelo: document.getElementById("orden-nuevo-vehiculo-modelo").value.trim(),
        anio: document.getElementById("orden-nuevo-vehiculo-anio").value.trim(),
        placa: document.getElementById("orden-nuevo-vehiculo-placa").value.trim(),
        kilometraje: kilometrajeVisita,
      };
      const { data, error } = await sb.from("vehiculos").insert(nuevoVehiculo).select().single();
      if (error) {
        console.error(error);
      showToast(t("error_guardar_vehiculo"), true);
        return;
      }
      vehiculo = data;
      vehiculoId = data.id;
      state.vehiculos.push(data);
    } else if (vehiculoId) {
      vehiculo = state.vehiculos.find((v) => v.id === vehiculoId);
    }

    const payload = {
      cliente_id: clienteId,
      kilometraje: kilometrajeVisita,
      vehiculo_id: vehiculoId || null,
      vehiculo_marca: vehiculo ? vehiculo.marca || "" : "",
      vehiculo_modelo: vehiculo ? vehiculo.modelo || "" : "",
      vehiculo_anio: vehiculo ? vehiculo.anio || "" : "",
      vehiculo_placa: vehiculo ? vehiculo.placa || "" : "",
      fecha_recepcion: document.getElementById("orden-fecha-recepcion").value,
      fecha_estimada: document.getElementById("orden-fecha-estimada").value || null,
      diagnostico: document.getElementById("orden-diagnostico").value.trim(),
      trabajo_recomendado: document.getElementById("orden-trabajo").value.trim(),
      notas: document.getElementById("orden-notas").value.trim(),
      check_frenos: document.getElementById("orden-check-frenos").checked,
      check_luces: document.getElementById("orden-check-luces").checked,
      check_llantas: document.getElementById("orden-check-llantas").checked,
      check_fluidos: document.getElementById("orden-check-fluidos").checked,
    };

    let ordenId = id;

    if (id) {
      const { error } = await sb.from("ordenes_servicio").update(payload).eq("id", id);
      if (error) {
        showToast("No se pudo guardar la orden.", true);
        return;
      }
    } else {
      payload.etapa = "diagnostico";
      payload.creado_por = state.empleadoActualId;
      const { data, error } = await sb.from("ordenes_servicio").insert(payload).select().single();
      if (error) {
        showToast("No se pudo guardar la orden.", true);
        return;
      }
      ordenId = data.id;
      await crearLlamadaPendiente(ordenId, "recibido");
    }

    // Restaurar el stock de las piezas que ya estaban antes de este guardado.
    for (const old of ordenPiezasOriginal) {
      await adjustPiezaStock(old.pieza_id, Number(old.cantidad));
    }
    await sb.from("orden_piezas").delete().eq("orden_id", ordenId);

    const nuevasPiezas = collectOrdenPiezas();
    for (const item of nuevasPiezas) {
      await adjustPiezaStock(item.pieza_id, -item.cantidad);
    }
    if (nuevasPiezas.length) {
      const piezasPayload = nuevasPiezas.map((it) => Object.assign({}, it, { orden_id: ordenId }));
      await sb.from("orden_piezas").insert(piezasPayload);
    }

    if (vehiculoId && kilometrajeVisita) {
      const vehiculoPrevio = state.vehiculos.find((veh) => veh.id === vehiculoId);
      const kilometrajeAnterior = vehiculoPrevio ? vehiculoPrevio.kilometraje : null;
      const { error: errorKm } = await sb.from("vehiculos").update({ kilometraje: kilometrajeVisita }).eq("id", vehiculoId);
      if (!errorKm) {
        if (vehiculoPrevio) vehiculoPrevio.kilometraje = kilometrajeVisita;
        if (kilometrajeAnterior !== kilometrajeVisita) {
          await registrarKilometraje(vehiculoId, kilometrajeVisita);
        }
      }
    }

    closeModal("modal-orden");
    showToast("Orden guardada.");
    await refreshPiezas();
    await refreshOrdenes();
  }

  async function deleteOrden() {
    const id = document.getElementById("orden-id").value;
    if (!id) return;
    if (!(await confirmDialog(t("confirm_eliminar_orden"), { title: t("eliminar_orden_titulo") }))) return;

    for (const old of ordenPiezasOriginal) {
      await adjustPiezaStock(old.pieza_id, Number(old.cantidad));
    }

    const { error } = await sb.from("ordenes_servicio").delete().eq("id", id);
    if (error) {
      showToast("No se pudo eliminar la orden.", true);
      return;
    }

    closeModal("modal-orden");
    showToast("Orden eliminada.");
    await refreshPiezas();
    await refreshOrdenes();
  }

