  function updateQuickAccessBadges() {
    const counts = {
      ordenes: state.ordenes.filter((o) => o.etapa !== "facturado" && o.etapa !== "cancelado").length,
      inventario: state.piezas.filter((p) => Number(p.stock) <= Number(p.stock_minimo)).length,
      facturas: state.facturas.filter((f) => f.estado === "pendiente").length,
      estimados: state.estimados.filter((e) => e.estado === "pendiente").length,
      llamadas: (state.llamadas || []).length,
      turnos: (state.turnos || []).filter((tu) => tu.estado === "esperando").length,
      "registro-diario": state.registroDiarioSinGuardarAyer || 0,
    };
    QUICK_ACCESS.forEach((q) => {
      if (!q.badge) return;
      const el = document.querySelector('[data-badge="' + q.view + '"]');
      if (!el) return;
      const n = counts[q.view] || 0;
      el.className = "quick-tile-badge is-" + q.badge;
      el.textContent = String(n);
      el.hidden = n === 0;
    });
  }

  let dashboardCalendarioMesActual = null;

  function renderDashboardMiniCalendario(mesActual) {
    dashboardCalendarioMesActual = mesActual;
    const [anio, mes] = mesActual.split("-").map(Number);
    document.getElementById("dashboard-calendario-mes-label").textContent = MESES[mes - 1] + " " + anio;

    const citasPorFecha = {};
    state.citas.forEach((c) => {
      if ((c.fecha || "").slice(0, 7) === mesActual) {
        citasPorFecha[c.fecha] = (citasPorFecha[c.fecha] || 0) + 1;
      }
    });

    const ultimoDiaNum = new Date(anio, mes, 0).getDate();
    const primerDiaSemana = new Date(anio, mes - 1, 1).getDay();
    const hoy = todayISO();

    let celdas = "";
    for (let i = 0; i < primerDiaSemana; i++) celdas += '<div class="mini-cal-dia mini-cal-dia-vacio"></div>';
    for (let dia = 1; dia <= ultimoDiaNum; dia++) {
      const fecha = mesActual + "-" + String(dia).padStart(2, "0");
      const cantidad = citasPorFecha[fecha] || 0;
      const etiquetaDia = cantidad ? t("mini_cal_dia_con_citas", { dia, cantidad }) : t("mini_cal_dia_sin_citas", { dia });
      celdas +=
        '<button type="button" class="mini-cal-dia' +
        (fecha === hoy ? " es-hoy" : "") +
        '" data-fecha="' +
        fecha +
        '" aria-label="' +
        escapeHtml(etiquetaDia) +
        '">' +
        dia +
        (cantidad ? '<span class="mini-cal-dot"></span>' : "") +
        "</button>";
    }

    const grid = document.getElementById("dashboard-mini-calendario-grid");
    grid.innerHTML = celdas;
    grid.querySelectorAll(".mini-cal-dia[data-fecha]").forEach((btn) => {
      btn.addEventListener("click", () => goToView("reservas"));
    });
  }

  async function renderMecanicoDelMes() {
    const hoyDate = new Date(todayISO() + "T00:00:00");
    const desde = hoyDate.getFullYear() + "-" + String(hoyDate.getMonth() + 1).padStart(2, "0") + "-01";
    const hasta = todayISO();
    const items = await fetchRegistroDiarioRango(desde, hasta);
    const el = document.getElementById("dashboard-mecanico-mes");
    if (!el) return;

    const totales = {};
    items.forEach((it) => {
      const total = (Number(it.labor) || 0) + (Number(it.piezas) || 0) + (Number(it.otro) || 0);
      totales[it.mecanico_id] = (totales[it.mecanico_id] || 0) + total;
    });
    const entries = Object.entries(totales).sort((a, b) => b[1] - a[1]);
    if (!entries.length) {
      el.innerHTML = '<p class="detalle-empty">' + t("sin_datos_mecanico_mes") + "</p>";
      return;
    }
    const [mecanicoId, total] = entries[0];
    const mecanico = state.mecanicos.find((m) => m.id === mecanicoId);
    el.innerHTML =
      avatarHtml(mecanico ? mecanico.nombre : "?", "avatar-lg") +
      '<div><strong style="font-size:1.05rem;">' +
      escapeHtml(mecanico ? mecanico.nombre : "—") +
      '</strong><div class="view-sub" style="margin:.15rem 0 0;">' +
      money(total) +
      " " +
      t("mecanico_mes_generado_label") +
      "</div></div>";
  }

  function renderDashboard() {
    const hoy = todayISO();
    const mesActual = hoy.slice(0, 7);

    const saludoEl = document.getElementById("dashboard-saludo");
    const nombreActual = state.empleadoActualId ? nombreEmpleado(state.empleadoActualId) : "";
    saludoEl.hidden = !nombreActual;
    if (nombreActual) saludoEl.textContent = t("saludo_dashboard", { nombre: nombreActual });

    const ingresosMes = state.facturas
      .filter((f) => f.estado === "pagada" && (f.fecha || "").slice(0, 7) === mesActual)
      .reduce((sum, f) => sum + Number(f.total), 0);

    const [anioActual, mesNum] = mesActual.split("-");
    const mesAnioPasado = String(Number(anioActual) - 1) + "-" + mesNum;
    const ingresosMesAnioPasado = state.facturas
      .filter((f) => f.estado === "pagada" && (f.fecha || "").slice(0, 7) === mesAnioPasado)
      .reduce((sum, f) => sum + Number(f.total), 0);

    const comparacionEl = document.getElementById("kpi-ingresos-comparacion");
    if (ingresosMesAnioPasado > 0) {
      const cambio = ((ingresosMes - ingresosMesAnioPasado) / ingresosMesAnioPasado) * 100;
      comparacionEl.hidden = false;
      comparacionEl.textContent = (cambio >= 0 ? "▲ " : "▼ ") + t("vs_mismo_mes_anio_pasado", { pct: Math.abs(cambio).toFixed(0) });
      comparacionEl.style.color = cambio >= 0 ? "var(--success)" : "var(--danger)";
    } else {
      comparacionEl.hidden = true;
    }

    const pendientes = state.facturas.filter((f) => f.estado === "pendiente");
    const pendientesMonto = pendientes.reduce((sum, f) => sum + Number(f.total), 0);

    const ordenesActivas = state.ordenes.filter((o) => o.etapa !== "facturado" && o.etapa !== "cancelado");

    const stockBajo = state.piezas.filter((p) => Number(p.stock) <= Number(p.stock_minimo));

    document.getElementById("kpi-ingresos").textContent = money(ingresosMes);
    document.getElementById("kpi-facturas-pendientes").textContent = String(pendientes.length);
    document.getElementById("kpi-facturas-pendientes-monto").textContent = money(pendientesMonto);
    document.getElementById("kpi-ordenes-activas").textContent = String(ordenesActivas.length);
    document.getElementById("kpi-stock-bajo").textContent = String(stockBajo.length);
    document.querySelectorAll(".kpi-value").forEach((el) => {
      el.classList.remove("is-updated");
      requestAnimationFrame(() => el.classList.add("is-updated"));
    });

    const citasHoy = state.citas.filter((c) => c.fecha === hoy);
    const cobradoHoy = state.facturas.filter((f) => f.estado === "pagada" && (f.fecha_pagada || f.fecha) === hoy).reduce((sum, f) => sum + Number(f.total), 0);
    document.getElementById("hoy-citas").textContent = String(citasHoy.length);
    document.getElementById("hoy-ordenes-activas").textContent = String(ordenesActivas.length);
    document.getElementById("hoy-cobrado").textContent = money(cobradoHoy);

    const mismoDiaSemanaPasada = sumarDias(hoy, -7);
    const cobradoSemanaPasada = state.facturas
      .filter((f) => f.estado === "pagada" && (f.fecha_pagada || f.fecha) === mismoDiaSemanaPasada)
      .reduce((sum, f) => sum + Number(f.total), 0);
    const comparacionSemanaEl = document.getElementById("hoy-cobrado-comparacion");
    if (cobradoSemanaPasada > 0) {
      const cambioSemana = ((cobradoHoy - cobradoSemanaPasada) / cobradoSemanaPasada) * 100;
      comparacionSemanaEl.hidden = false;
      comparacionSemanaEl.textContent = (cambioSemana >= 0 ? "▲ " : "▼ ") + Math.abs(cambioSemana).toFixed(0) + "% " + t("vs_mismo_dia_semana_pasada");
      comparacionSemanaEl.style.color = cambioSemana >= 0 ? "var(--success)" : "var(--danger)";
    } else {
      comparacionSemanaEl.hidden = true;
    }

    renderDashboardMiniCalendario(dashboardCalendarioMesActual || hoy.slice(0, 7));
    renderMecanicoDelMes();

    const counts = document.getElementById("dashboard-etapa-counts");
    counts.innerHTML = ETAPAS.map((etapa) => {
      const n = state.ordenes.filter((o) => o.etapa === etapa.key).length;
      return '<span class="etapa-count-item">' + t(etapa.labelKey) + ": <strong>" + n + "</strong></span>";
    }).join("");

    const pagadas = state.facturas.filter((f) => f.estado === "pagada").sort((a, b) => (a.fecha < b.fecha ? 1 : -1));
    const pendientesOrdenadas = pendientes.slice().sort((a, b) => (a.fecha < b.fecha ? 1 : -1));

    renderPagoPanel("pago-panel-pendientes", pendientesOrdenadas, false);
    renderPagoPanel("pago-panel-pagadas", pagadas, true);
    document.getElementById("pago-panel-pendientes-count").textContent = String(pendientesOrdenadas.length);
    document.getElementById("pago-panel-pagadas-count").textContent = String(pagadas.length);

    const facturasVencidas = pendientes.filter((f) => facturaVencida(f));
    const bannerVencidas = document.getElementById("dashboard-banner-vencidas");
    bannerVencidas.hidden = !facturasVencidas.length;
    if (facturasVencidas.length) {
      const montoVencido = facturasVencidas.reduce((sum, f) => sum + Number(f.total), 0);
      bannerVencidas.textContent = t("facturas_vencidas_dashboard", { n: facturasVencidas.length, monto: money(montoVencido) });
    }

    renderRecordatoriosPendientes();
    renderDashboardChart();
    updateQuickAccessBadges();
  }

  function renderRecordatoriosPendientes() {
    const hoy = todayISO();
    const panel = document.getElementById("dashboard-recordatorios-panel");
    const lista = document.getElementById("dashboard-recordatorios-lista");

    const pendientes = state.vehiculos.filter((v) => v.recordatorio_activo && v.recordatorio_proxima_fecha && v.recordatorio_proxima_fecha <= hoy);

    if (!pendientes.length) {
      panel.hidden = true;
      lista.innerHTML = "";
      return;
    }

    panel.hidden = false;
    lista.innerHTML = pendientes
      .map((v) => {
        const cliente = state.clientes.find((c) => c.id === v.cliente_id);
        return (
          '<div class="detalle-list-item" data-vehiculo-recordatorio-id="' +
          v.id +
          '"><span style="flex:1;">' +
          escapeHtml(cliente ? cliente.nombre : "—") +
          " — " +
          escapeHtml(vehiculoLabel(v)) +
          "</span><span>" +
          escapeHtml((cliente && cliente.telefono) || "—") +
          "</span><span>" +
          escapeHtml(formatDate(v.recordatorio_proxima_fecha)) +
          '</span><button type="button" class="btn-ghost btn-ya-avise">' +
          t("btn_ya_avise") +
          "</button></div>"
        );
      })
      .join("");

    lista.querySelectorAll(".btn-ya-avise").forEach((btn) => {
      btn.addEventListener("click", () => {
        const fila = btn.closest("[data-vehiculo-recordatorio-id]");
        marcarRecordatorioAvisado(fila.dataset.vehiculoRecordatorioId);
      });
    });
  }

  async function marcarRecordatorioAvisado(vehiculoId) {
    const vehiculo = state.vehiculos.find((v) => v.id === vehiculoId);
    if (!vehiculo) return;
    const hoy = todayISO();
    const proxima = new Date(hoy);
    proxima.setMonth(proxima.getMonth() + (Number(vehiculo.recordatorio_frecuencia_meses) || 3));
    const proximaISO = proxima.toISOString().slice(0, 10);

    const { error } = await sb
      .from("vehiculos")
      .update({ recordatorio_ultima_fecha: hoy, recordatorio_proxima_fecha: proximaISO })
      .eq("id", vehiculoId);
    if (error) {
      showToast(t("error_actualizar_recordatorio"), true);
      return;
    }
    vehiculo.recordatorio_ultima_fecha = hoy;
    vehiculo.recordatorio_proxima_fecha = proximaISO;
    showToast(t("recordatorio_actualizado_msg"));
    renderRecordatoriosPendientes();
  }

  function renderDashboardChart() {
    const canvas = document.getElementById("dashboard-chart");
    if (!canvas || !canvas.getContext) return;
    const ctx = canvas.getContext("2d");

    const cssWidth = canvas.clientWidth || 600;
    canvas.width = cssWidth;
    canvas.height = 180;
    const W = canvas.width;
    const H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    const hoy = new Date(todayISO());
    const meses = [];
    for (let i = 5; i >= 0; i--) {
      const d = new Date(hoy.getFullYear(), hoy.getMonth() - i, 1);
      const key = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
      meses.push({ key, label: MESES[d.getMonth()].slice(0, 3) });
    }

    const totales = meses.map((m) => state.facturas.filter((f) => f.estado === "pagada" && (f.fecha || "").slice(0, 7) === m.key).reduce((sum, f) => sum + Number(f.total), 0));
    const max = Math.max(1, ...totales);

    const paddingBottom = 28;
    const paddingTop = 22;
    const plotH = H - paddingBottom - paddingTop;
    const n = meses.length;
    const gap = 14;
    const barW = (W - gap * (n + 1)) / n;

    const styles = getComputedStyle(document.documentElement);
    const textDim = styles.getPropertyValue("--text-dim").trim() || "#68707e";
    const textFaint = styles.getPropertyValue("--text-faint").trim() || "#98a1b0";
    const barColores = [1, 2, 3, 4, 5, 6, 7, 8].map((n) => styles.getPropertyValue("--series-" + n).trim()).filter(Boolean);

    ctx.font = "11px -apple-system, sans-serif";
    ctx.textAlign = "center";

    meses.forEach((m, i) => {
      const x = gap + i * (barW + gap);
      const h = (totales[i] / max) * plotH;
      const y = paddingTop + (plotH - h);

      ctx.fillStyle = barColores.length ? barColores[i % barColores.length] : "#d5601a";
      if (ctx.roundRect) {
        ctx.beginPath();
        ctx.roundRect(x, y, barW, Math.max(h, 2), [4, 4, 0, 0]);
        ctx.fill();
      } else {
        ctx.fillRect(x, y, barW, Math.max(h, 2));
      }

      ctx.fillStyle = textDim;
      ctx.fillText(m.label, x + barW / 2, H - paddingBottom + 16);

      if (totales[i] > 0) {
        ctx.fillStyle = textFaint;
        ctx.fillText(money(totales[i]).replace(".00", ""), x + barW / 2, y - 6);
      }
    });
  }

  function renderPagoPanel(containerId, facturasList, soloLectura) {
    const el = document.getElementById(containerId);
    if (!facturasList.length) {
      el.innerHTML = '<p class="detalle-empty">Nada por aquí.</p>';
      return;
    }
    el.innerHTML = facturasList
      .map(
        (f) =>
          '<div class="pago-item" data-pago-factura="' +
          f.id +
          '"><span class="pago-item-cliente">' +
          avatarHtml(f.clientes ? f.clientes.nombre : "—", "avatar-sm") +
          escapeHtml(f.clientes ? f.clientes.nombre : "—") +
          "</span><span class=\"pago-item-meta\">" +
          money(f.total) +
          " · " +
          escapeHtml(formatDate(f.fecha)) +
          "</span></div>"
      )
      .join("");
    el.querySelectorAll("[data-pago-factura]").forEach((row) => {
      makeRowActivatable(row, () => {
        if (soloLectura) {
          printFactura(row.dataset.pagoFactura, true);
          return;
        }
        const factura = state.facturas.find((f) => f.id === row.dataset.pagoFactura);
        if (factura) openFacturaModal(factura);
      });
    });
  }

